/// Each line's 8-bit code leads back to its face: every face has a code of its own on each
/// line, so the tables follow from the one above.
private func facesByCode(_ code: KeyPath<FaceWithUnderlineAndOverlineCode, UInt8>) -> [FaceWithUnderlineAndOverlineCode?] {
    var table = [FaceWithUnderlineAndOverlineCode?](repeating: nil, count: 256)
    for face in letterIndexTimesSixPlusDigitIndexFaceWithUndoverlineCodes {
        table[Int(face[keyPath: code])] = face
    }
    return table
}

public let underlineCodeToFaceWithUnderlineAndOverlineCode = facesByCode(\.underlineCode)
public let overlineCodeToFaceWithUnderlineAndOverlineCode = facesByCode(\.overlineCode)
